node -e "
const { roundRatio } = require('./src/rounding');
// half-even contract: 0.5->0, 1.5->2, -0.5->0, -1.5->-2, 2.5->2, 3.5->4
const cases = [[5n,10n,0],[15n,10n,2],[-5n,10n,0],[-15n,10n,-2],[25n,10n,2],[35n,10n,4],[7n,10n,1],[-7n,10n,-1]];
for (const [n,d,want] of cases) {
  const got = roundRatio(n,d);
  if (got !== want) throw new Error(\`\${n}/\${d}: got \${got} want \${want}\`);
}
// exactness beyond double precision: 2^53+1 over 2 -> 4503599627370496.5 -> half-even -> 4503599627370496
const big = roundRatio(9007199254740993n, 2n);
if (big !== 4503599627370496) throw new Error('big half-even failed: ' + big);
// unsafe result must throw RangeError
try { roundRatio(BigInt(Number.MAX_SAFE_INTEGER) * 4n, 1n); throw new Error('no throw'); }
catch (e) { if (!(e instanceof RangeError)) throw e; }
// -0 normalization
if (!Object.is(roundRatio(-1n, 4n), 0)) throw new Error('-0 leak');
// validation
try { roundRatio(1, 2n); throw new Error('no type throw'); } catch (e) { if (!(e instanceof TypeError)) throw e; }
try { roundRatio(1n, 0n); throw new Error('no range throw'); } catch (e) { if (!(e instanceof RangeError)) throw e; }
console.log('rounding contract OK');

const { buildInvoice } = require('./src');
// credits + invoice discounts + invoice tax mode sanity
const inv = buildInvoice({ currency: 'USD', taxMode: 'invoice',
  discounts: [{ type: 'percent', rateBps: 1000 }],
  lines: [
    { unitCents: 1000, taxBps: 1000 },
    { unitCents: 333, taxBps: 1000 },
    { unitCents: -200, taxBps: 1000 },
  ]});
console.log(JSON.stringify(inv.lines.map(l => [l.netCents, l.taxCents, l.totalCents])), inv.netCents, inv.taxCents, inv.totalCents);
// fixed-before-percent now honors supplied order (no longer re-sorted)
const r = buildInvoice({ currency: 'USD', lines: [{ unitCents: 105, discounts: [{type:'fixed',amountCents:10},{type:'percent',rateBps:5000}] }] });
console.log('fixed-then-percent net:', r.netCents); // 95 -> 47.5 -> half-even 48 -> 47
"

